  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'If a graph of 1/v against 1/u gives a straight line, the relationship between u and v is:', '["Linear","Quadratic","Reciprocal/linear","Exponential"]'::jsonb, 2, 'The correct answer is: Reciprocal/linear.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'In a linear graph y = mx + c, if c = 0 and m is negative, the graph:', '["Passes through origin with positive slope","Passes through origin with negative slope","Has a positive intercept","Has a negative slope and positive intercept"]'::jsonb, 1, 'The correct answer is: Passes through origin with negative slope.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'Which of the following best describes a graph with a hyperbolic shape?', '["y is directly proportional to x","y is directly proportional to x²","y is inversely proportional to x","y is independent of x"]'::jsonb, 2, 'The correct answer is: y is inversely proportional to x.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A graph of T² against L for a simple pendulum gives a straight line whose slope equals:', '["g/4π²","4π²/g","2π/g","g/2π"]'::jsonb, 1, 'The correct answer is: 4π²/g.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The intercept on the y-axis of the graph y = 5x − 3 is:', '["5","3","−3","−5"]'::jsonb, 2, 'The correct answer is: −3.', 'Graphs and Linearisation', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'In error analysis, the best-fit line on a graph is drawn to:', '["Connect all data points","Pass through the origin always","Minimize overall deviation from data points","Maximize the slope"]'::jsonb, 2, 'The correct answer is: Minimize overall deviation from data points.', 'Measurement and Error Analysis', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The period of a simple pendulum depends on:', '["Mass of the bob","Amplitude of oscillation","Length of the pendulum","Material of the bob"]'::jsonb, 2, 'The correct answer is: Length of the pendulum.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The acceleration of a body undergoing SHM is:', '["Proportional to displacement and in same direction","Proportional to displacement and in opposite direction","Constant throughout the motion","Zero at maximum displacement"]'::jsonb, 1, 'The correct answer is: Proportional to displacement and in opposite direction.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'At the equilibrium position of a body in SHM, the:', '["Potential energy is maximum","Kinetic energy is zero","Velocity is maximum","Acceleration is maximum"]'::jsonb, 2, 'The correct answer is: Velocity is maximum.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The period of a mass-spring system is given by:', '["T = 2π√(k/m)","T = 2π√(m/k)","T = 2π√(g/L)","T = 2π√(L/g)"]'::jsonb, 1, 'The correct answer is: T = 2π√(m/k).', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'For a simple pendulum of length 1m, taking g = 10m/s², the period is approximately:', '["3.14 s","6.28 s","1.99 s","0.50 s"]'::jsonb, 2, 'For $T = 2\pi\sqrt{L/g}$ with $L = 1\ \text{m}$ and $g = 10$: $T \approx 1.99\ \text{s}$.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The total mechanical energy of a body in SHM is:', '["Zero","Constant","Maximum at equilibrium","Minimum at equilibrium"]'::jsonb, 1, 'The correct answer is: Constant.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'At maximum displacement in SHM:', '["Kinetic energy is maximum","Potential energy is zero","Potential energy is maximum","Velocity is maximum"]'::jsonb, 2, 'The correct answer is: Potential energy is maximum.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'The frequency of SHM is defined as:', '["Number of oscillations per minute","Time for one complete oscillation","Number of complete oscillations per second","Distance covered per second"]'::jsonb, 2, 'The correct answer is: Number of complete oscillations per second.', 'Simple Harmonic Motion', false, 'first', 1),
  ('phy-107-practical-physics-1', 'PHY 107: General Physics Practical I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering, Faculty of Biological Sciences, Faculty of Veterinary Medicine, Faculty of Environmental Studies', 'Physics and Astronomy', '100 Level', 'A spring of force constant 200 N/m has a 0.5 kg mass attached. Its angular frequency is:', '["10 rad/s","20 rad/s","40 rad/s","400 rad/s"]'::jsonb, 1, '$\omega = \sqrt{k/m} = \sqrt{200/0.5} = 20\ \text{rad/s}$.', 'Simple Harmonic Motion', false, 'first', 1),
